module escape_speed(\n    input wire clk, \n    input wire rst_n, \n    input wire start, \n    \n    input wire [2:0] n, \n    input wire [2:0] m, \n    input wire [2:0] e, \n    input wire [2:0] b, \n    input wire [2:0] p, \n    \n    input wire [2:0] exit0, input wire [2:0] exit1, input wire [2:0] exit2, input wire [2:0] exit3, \n    input wire [2:0] exit4, input wire [2:0] exit5, input wire [2:0] exit6, input wire [2:0] exit7, \n    \n    input wire [2:0] edge_a0, input wire [2:0] edge_b0, input wire [7:0] edge_l0, input wire edge_valid0, \n    input wire [2:0] edge_a1, input wire [2:0] edge_b1, input wire [7:0] edge_l1, input wire edge_valid1, \n    input wire [2:0] edge_a2, input wire [2:0] edge_b2, input wire [7:0] edge_l2, input wire edge_valid2, \n    input wire [2:0] edge_a3, input wire [2:0] edge_b3, input wire [7:0] edge_l3, input wire edge_valid3, \n    input wire [2:0] edge_a4, input wire [2:0] edge_b4, input wire [7:0] edge_l4, input wire edge_valid4, \n    input wire [2:0] edge_a5, input wire [2:0] edge_b5, input wire [7:0] edge_l5, input wire edge_valid5, \n    input wire [2:0] edge_a6, input wire [2:0] edge_b6, input wire [7:0] edge_l6, input wire edge_valid6, \n    input wire [2:0] edge_a7, input wire [2:0] edge_b7, input wire [7:0] edge_l7, input wire edge_valid7, \n    \n    output reg [31:0] speed_q16, \n    output reg impossible, \n    output reg done\n);\n    \n    // State definitions\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] RESET_DIST     = 4'd1;\n    localparam [3:0] FLOYD_K_LOOP   = 4'd2;\n    localparam [3:0] FLOYD_I_LOOP   = 4'd3;\n    localparam [3:0] FLOYD_J_LOOP   = 4'd4;\n    localparam [3:0] FLOYD_UPDATE   = 4'd5;\n    localparam [3:0] COMPUTE_W      = 4'd6;\n    localparam [3:0] DIJKSTRA_INIT  = 4'd7;\n    localparam [3:0] DIJKSTRA_SELECT= 4'd8;\n    localparam [3:0] DIJKSTRA_RELAX = 4'd9;\n    localparam [3:0] DIJKSTRA_UPDATE= 4'd10;\n    localparam [3:0] FIND_MIN_EXIT  = 4'd11;\n    localparam [3:0] COMPUTE_SPEED  = 4'd12;\n    localparam [3:0] DIVIDER        = 4'd13;\n    localparam [3:0] DONE_STATE     = 4'd14;\n    \n    reg [3:0] state, next_state;\n    \n    // Floyd-Warshall registers\n    reg [15:0] dist [0:7][0:7];\n    reg [2:0] k, i, j;\n    \n    // W registers\n    reg [31:0] w_num [0:7];\n    reg [31:0] w_den [0:7];\n    \n    // Dijkstra registers\n    reg [31:0] best_num [0:7];\n    reg [31:0] best_den [0:7];\n    reg visited [0:7];\n    reg [2:0] current_node;\n    \n    // Exit processing\n    reg [2:0] exit_nodes [0:7];\n    reg [2:0] exit_index;\n    reg found_min;\n    reg [31:0] min_num, temp_min_num;\n    reg [31:0] min_den, temp_min_den;\n    \n    // Division variables\n    reg [63:0] dividend;\n    reg [31:0] divisor;\n    reg [31:0] quotient;\n    reg [5:0] div_counter;\n    \n    // Temporary variables\n    reg [15:0] dist_kj;\n    reg [15:0] dist_ik_plus_kj;\n    reg [31:0] temp_num;\n    reg [31:0] temp_den;\n    wire [63:0] cross_comp_a;\n    wire [63:0] cross_comp_b;\n    \n    // Loop counters\n    integer idx;\n    genvar x, y;\n    \n    // Cyclometer to prevent infinite loops\n    reg [15:0] cycle_counter;\n    localparam [15:0] MAX_CYCLES = 16'd4000;\n    \n    assign cross_comp_a = best_num[j] * best_den[current_node];\n    assign cross_comp_b = best_num[current_node] * best_den[j];\n    \n    // Extract edges into array\n    wire [2:0] edge_a[0:7];\n    wire [2:0] edge_b[0:7];\n    wire [7:0] edge_l[0:7];\n    wire edge_valid[0:7];\n    \n    assign edge_a = '{edge_a0, edge_a1, edge_a2, edge_a3, edge_a4, edge_a5, edge_a6, edge_a7};\n    assign edge_b = '{edge_b0, edge_b1, edge_b2, edge_b3, edge_b4, edge_b5, edge_b6, edge_b7};\n    assign edge_l = '{edge_l0, edge_l1, edge_l2, edge_l3, edge_l4, edge_l5, edge_l6, edge_l7};\n    assign edge_valid = '{edge_valid0, edge_valid1, edge_valid2, edge_valid3, \n                        edge_valid4, edge_valid5, edge_valid6, edge_valid7};\n    \n    // Exit nodes array\n    always @(*) begin\n        exit_nodes = '{exit0, exit1, exit2, exit3, exit4, exit5, exit6, exit7};\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            speed_q16 <= 32'd0;\n            cycle_counter <= 16'd0;\n            \n            // Initialize all arrays (individual element assignment)\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                w_num[idx] <= 32'h7FFF_FFFF;\n                w_den[idx] <= 32'd1;\n                best_num[idx] <= 32'h7FFF_FFFF;\n                best_den[idx] <= 32'd1;\n                visited[idx] <= 1'b0;\n                for (int jdx = 0; jdx < 8; jdx = jdx + 1) begin\n                    dist[idx][jdx] <= 16'hFFFF;\n                end\n            end\n        end else begin\n            cycle_counter <= cycle_counter + 16'd1;\n            \n            // Main state machine\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    speed_q16 <= 32'd0;\n                    if (start) begin\n                        state <= RESET_DIST;\n                    end\n                end\n                \n                RESET_DIST: begin\n                    // Set diagonals to 0\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        dist[idx][idx] <= 16'd0;\n                    end\n                    \n                    // Apply edges (both directions)\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        if (edge_valid[idx] && (edge_a[idx] < n) && (edge_b[idx] < n)) begin\n                            dist[edge_a[idx]][edge_b[idx]] <= {8'd0, edge_l[idx]};\n                            dist[edge_b[idx]][edge_a[idx]] <= {8'd0, edge_l[idx]};\n                        end\n                    end\n                    \n                    k <= 3'd0;\n                    state <= FLOYD_K_LOOP;\n                end\n                \n                FLOYD_K_LOOP: begin\n                    if (k >= n) begin\n                        state <= COMPUTE_W;\n                    end else begin\n                        i <= 3'd0;\n                        state <= FLOYD_I_LOOP;\n                    end\n                end\n                \n                FLOYD_I_LOOP: begin\n                    if (i >= n) begin\n                        k <= k + 3'd1;\n                        state <= FLOYD_K_LOOP;\n                    end else begin\n                        j <= 3'd0;\n                        state <= FLOYD_J_LOOP;\n                    end\n                end\n                \n                FLOYD_J_LOOP: begin\n                    if (j >= n) begin\n                        i <= i + 3'd1;\n                        state <= FLOYD_I_LOOP;\n                    end else begin\n                        dist_kj <= dist[k][j];\n                        dist_ik_plus_kj <= dist[i][k] + dist[k][j];\n                        state <= FLOYD_UPDATE;\n                    end\n                end\n                \n                FLOYD_UPDATE: begin\n                    if (dist_ik_plus_kj < dist[i][j]) begin\n                        dist[i][j] <= dist_ik_plus_kj;\n                    end\n                    j <= j + 3'd1;\n                    state <= FLOYD_J_LOOP;\n                end\n                \n                COMPUTE_W: begin\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        if (idx < n) begin\n                            // Check if dist[p][idx] is zero\n                            if (dist[p][idx] == 16'd0) begin\n                                w_num[idx] <= 32'h7FFF_FFFF;\n                                w_den[idx] <= 32'd1;\n                            end else begin\n                                w_num[idx] <= (32'd160 * dist[b][idx]);\n                                w_den[idx] <= dist[p][idx];\n                            end\n                        end else begin\n                            w_num[idx] <= 32'h7FFF_FFFF;\n                            w_den[idx] <= 32'd1;\n                        end\n                    end\n                    state <= DIJKSTRA_INIT;\n                end\n                \n                DIJKSTRA_INIT: begin\n                    // Initialize Dijkstra\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        if (idx < n) begin\n                            best_num[idx] <= (idx == b) ? 32'd0 : 32'h7FFF_FFFF;\n                            best_den[idx] <= 32'd1;\n                            visited[idx] <= 1'b0;\n                        end else begin\n                            best_num[idx] <= 32'h7FFF_FFFF;\n                            best_den[idx] <= 32'd1;\n                            visited[idx] <= 1'b1;\n                        end\n                    end\n                    current_node <= b;\n                    state <= DIJKSTRA_SELECT;\n                end\n                \n                DIJKSTRA_SELECT: begin\n                    reg [2:0] min_node;\n                    reg [31:0] min_num_temp;\n                    reg [31:0] min_den_temp;\n                    reg found;\n                    \n                    min_node = 3'd0;\n                    min_num_temp = 32'h7FFF_FFFF;\n                    min_den_temp = 32'd1;\n                    found = 1'b0;\n                    \n                    for (idx = 0; idx < n; idx = idx + 1) begin\n                        if (!visited[idx] && (best_num[idx] * min_den_temp < min_num_temp * best_den[idx])) begin\n                            min_num_temp = best_num[idx];\n                            min_den_temp = best_den[idx];\n                            min_node = idx;\n                            found = 1'b1;\n                        end\n                    end\n                    \n                    if (found) begin\n                        current_node <= min_node;\n                        visited[min_node] <= 1'b1;\n                        state <= DIJKSTRA_RELAX;\n                    end else begin\n                        state <= FIND_MIN_EXIT;\n                    end\n                end\n                \n                DIJKSTRA_RELAX: begin\n                    // Relax edges from current_node\n                    j <= 3'd0;\n                    state <= DIJKSTRA_UPDATE;\n                end\n                \n                DIJKSTRA_UPDATE: begin\n                    if (j >= n) begin\n                        state <= DIJKSTRA_SELECT;\n                    end else begin\n                        if (dist[current_node][j] != 16'hFFFF) begin\n                            // Compute candidate = max(best[current_node], w[j])\n                            if (w_num[j] * best_den[current_node] > best_num[current_node] * w_den[j]) begin\n                                temp_num <= w_num[j];\n                                temp_den <= w_den[j];\n                            end else begin\n                                temp_num <= best_num[current_node];\n                                temp_den <= best_den[current_node];\n                            end\n                            \n                            // Compare with best[j]\n                            if (temp_num * best_den[j] < best_num[j] * temp_den) begin\n                                best_num[j] <= temp_num;\n                                best_den[j] <= temp_den;\n                            end\n                        end\n                        j <= j + 3'd1;\n                    end\n                end\n                \n                FIND_MIN_EXIT: begin\n                    min_num <= 32'h7FFF_FFFF;\n                    min_den <= 32'd1;\n                    exit_index <= 3'd0;\n                    state <= COMPUTE_SPEED;\n                end\n                \n                COMPUTE_SPEED: begin\n                    if (exit_index >= e) begin\n                        if (min_num == 32'h7FFF_FFFF) begin\n                            impossible <= 1'b1;\n                            state <= DONE_STATE;\n                        end else begin\n                            // Compute speed = 160 * M_den * 65536 / M_num\n                            dividend <= {min_den, 16'd0} * 64'd65536;\n                            divisor <= min_num;\n                            div_counter <= 6'd0;\n                            quotient <= 32'd0;\n                            state <= DIVIDER;\n                        end\n                    end else begin\n                        temp_min_num = best_num[exit_nodes[exit_index]];\n                        temp_min_den = best_den[exit_nodes[exit_index]];\n                        \n                        if (temp_min_num * min_den < min_num * temp_min_den) begin\n                            min_num <= temp_min_num;\n                            min_den <= temp_min_den;\n                        end\n                        \n                        exit_index <= exit_index + 3'd1;\n                    end\n                end\n                \n                DIVIDER: begin\n                    if (div_counter == 6'd32) begin\n                        speed_q16 <= quotient;\n                        state <= DONE_STATE;\n                    end else begin\n                        if (dividend >= {31'd0, divisor}) begin\n                            dividend <= dividend - {31'd0, divisor};\n                            quotient <= {quotient[30:0], 1'b1};\n                        end else begin\n                            quotient <= {quotient[30:0], 1'b0};\n                        end\n                        dividend <= dividend << 1;\n                        div_counter <= div_counter + 6'd1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n            \n            // Timeout handling\n            if (cycle_counter >= MAX_CYCLES) begin\n                state <= IDLE;\n                impossible <= 1'b1;\n                done <= 1'b1;\n            end\n        end\n    end\n\nendmodule